export const ui={en:{welcome:'Hello, explorer! Ask in English, Burmese or Chinese. I can explain space facts, remember the topic for follow-up questions, and show a different fact. I use a curated knowledge base, not a live AI service.',fallback:'I don’t have a reliable answer to that yet. Try naming a topic and a detail, such as “Why is Mars red?” or choose a suggestion below. I won’t guess.',clarify:'Which topic would you like to explore? Choose one below, or name a planet, the Sun, Moon, black holes or the Milky Way.',more:'Explain more',simple:'Explain simply',another:'Another fact',related:'Related fact',source:'Read the source ↗',greeting:'Hello! What would you like to discover about space?',unsupported:'I don’t have that specific detail in my knowledge base. Here are some questions I can answer about this topic.',end:'That is the last new fact I have about this topic for now. Choose another topic to keep exploring.',about:'Tell me about ',you:'YOU',guide:'ORBIT GUIDE',random:'↗ Random question',quiz:'✧ Quiz me',clear:'Clear',placeholder:'Ask a space question…',disclaimer:'Curated space guide · No live AI · Chat stays in this tab',ask:'Ask ORBIT',correct:'Correct!',wrong:'The correct answer is ',reset:'Conversation cleared.'},my:{welcome:'မင်္ဂလာပါ။ မြန်မာ၊ အင်္ဂလိပ် သို့မဟုတ် တရုတ်ဘာသာဖြင့် မေးနိုင်ပါသည်။ အာကာသအချက်အလက်များကို ရှင်းပြပြီး ဆက်မေးသည့်အကြောင်းအရာကို မှတ်ထားနိုင်ပါသည်။ တိုက်ရိုက် AI မဟုတ်ဘဲ စုစည်းထားသော အသိပညာကို အသုံးပြုသည်။',fallback:'ဒီမေးခွန်းအတွက် ယုံကြည်စိတ်ချရသောအဖြေ မရှိသေးပါ။ “အင်္ဂါဂြိုဟ် ဘာကြောင့်နီသလဲ” ကဲ့သို့ အကြောင်းအရာနှင့်အသေးစိတ်ကို မေးပါ၊ သို့မဟုတ် အောက်ပါမေးခွန်းရွေးပါ။ မသိသည့်အရာကို မခန့်မှန်းပါ။',clarify:'ဘယ်အကြောင်းကို လေ့လာချင်ပါသလဲ။ ဂြိုဟ်၊ နေ၊ လ၊ တွင်းနက် သို့မဟုတ် နဂါးငွေ့တန်းကို ရွေးပါ။',more:'ပိုမိုရှင်းပြပါ',simple:'ရိုးရိုးရှင်းပြပါ',another:'နောက်အချက်တစ်ခု',related:'ဆက်စပ်အချက်',source:'မူရင်းကိုဖတ်ရန် ↗',greeting:'မင်္ဂလာပါ။ အာကာသအကြောင်း ဘာသိချင်ပါသလဲ။',unsupported:'ဤအသေးစိတ်အချက်အတွက် အဖြေ မရှိသေးပါ။ ဒီအကြောင်းအရာနှင့်ပတ်သက်၍ ဖြေနိုင်သည့်မေးခွန်းများကို အောက်တွင်ရွေးနိုင်ပါသည်။',end:'ဒီအကြောင်းအရာအတွက် အချက်အသစ်များ ကုန်သွားပါပြီ။ နောက်အကြောင်းအရာတစ်ခုကို ရွေးပါ။',about:'အကြောင်းပြောပြပါ — ',you:'သင်',guide:'ORBIT လမ်းညွှန်',random:'↗ ကျပန်းမေးခွန်း',quiz:'✧ ဉာဏ်စမ်း',clear:'ရှင်းလင်းရန်',placeholder:'အာကာသမေးခွန်းမေးပါ…',disclaimer:'စုစည်းထားသောအသိပညာ · တိုက်ရိုက် AI မဟုတ် · စကားဝိုင်းကိုဤစာမျက်နှာတွင်သာထားသည်',ask:'ORBIT ကိုမေးရန်',correct:'မှန်ပါတယ်။',wrong:'အဖြေမှန်မှာ ',reset:'စကားဝိုင်းကိုရှင်းလင်းပြီးပါပြီ။'},zh:{welcome:'你好，探索者！你可以用中文、缅甸语或英语提问。我能解释太空知识、记住话题以便追问，也能提供另一条知识。我使用整理好的知识库，并非实时AI服务。',fallback:'我的知识库暂时没有这个问题的可靠答案。请注明话题和细节，例如“火星为什么是红色的？”，或选择下面的问题。我不会猜测答案。',clarify:'你想了解哪个话题？请选择，或说出某颗行星、太阳、月球、黑洞或银河系。',more:'详细解释',simple:'简单解释',another:'另一条知识',related:'相关知识',source:'阅读来源 ↗',greeting:'你好！你想探索哪些太空知识？',unsupported:'知识库暂时没有这项具体信息。你可以选择下面有关这个话题的问题。',end:'这个话题的所有新知识已经介绍完了。换一个话题继续探索吧。',about:'介绍一下',you:'你',guide:'ORBIT 向导',random:'↗ 随机问题',quiz:'✧ 小测验',clear:'清空',placeholder:'问一个太空问题…',disclaimer:'精选太空知识 · 非实时AI · 对话仅保留在本页',ask:'询问 ORBIT',correct:'答对了！',wrong:'正确答案是',reset:'对话已清空。'}};
export const extraTopics=[
{aliases:['nasa','နာဆာ','美国宇航局'],answer:{en:'NASA is the United States’ civilian space agency. It studies Earth and space, develops aeronautics, and conducts robotic and human exploration. Its work includes missions such as Hubble, Perseverance and Apollo.',my:'NASA သည် အမေရိကန်၏ အရပ်ဘက်အာကာသအဖွဲ့အစည်းဖြစ်သည်။ ကမ္ဘာနှင့်အာကာသကိုလေ့လာပြီး လေကြောင်းသုတေသနနှင့် လူ၊ စက်ရုပ်ပါဝင်သော အာကာသစူးစမ်းမှုများ လုပ်ဆောင်သည်။ Hubble၊ Perseverance နှင့် Apollo တို့ ပါဝင်သည်။',zh:'NASA是美国的民用航天机构，研究地球与宇宙、开展航空技术研究，并进行机器人和载人探索。哈勃、毅力号和阿波罗都是其任务的例子。'},source:'https://www.nasa.gov/'},
{aliases:['spacex','space x','စပေ့စ်အိတ်စ်'],answer:{en:'SpaceX develops rockets and spacecraft. Falcon 9 can recover and reuse its first stage; its upper stage continues toward orbit. Dragon carries crew or cargo. Starship’s design goal is to reuse both stages. This is an overview, not a live launch update.',my:'SpaceX သည် ဒုံးပျံနှင့်အာကာသယာဉ်များ တည်ဆောက်သည်။ Falcon 9 ၏ ပထမအဆင့်ကို ပြန်ဆင်း၍ ပြန်သုံးနိုင်ပြီး အပေါ်အဆင့်က ပတ်လမ်းသို့ဆက်သွားသည်။ Dragon က လူ သို့မဟုတ်ကုန်တင်သည်။ Starship ၏ ရည်ရွယ်ချက်မှာ အဆင့်နှစ်ခုလုံးပြန်သုံးရန်ဖြစ်သည်။ ယခုဖော်ပြချက်မှာ အကျဉ်းချုပ်သာဖြစ်သည်။',zh:'SpaceX研发火箭和飞船。猎鹰9号可回收复用第一级，上面级继续飞向轨道。龙飞船运送人员或货物。星舰的设计目标是两级都能复用。这里是原理概览，不是实时发射动态。'},source:'https://www.spacex.com/'},
{aliases:['rocket','launch','landing','ဒုံးပျံ','ဆင်းသက်','လွှတ်တင်','火箭','着陆','发射'],answer:{en:'A rocket accelerates by ejecting exhaust in the opposite direction. It carries its own propellant, so it works in space without pushing on air. During a powered landing, engine thrust slows the descent. In our Playground, hold thrust to brake and keep sideways speed low before touching the green pad.',my:'ဒုံးပျံသည် အိတ်ဇောဓာတ်ငွေ့ကို ဆန့်ကျင်ဘက်သို့ထုတ်လွှတ်၍ အရှိန်ရသည်။ ကိုယ်ပိုင်တွန်းကန်လောင်စာယူဆောင်သဖြင့် လေကိုတွန်းရန်မလိုဘဲ အာကာသတွင်လည်း အလုပ်လုပ်သည်။ ဆင်းသက်စဉ် အင်ဂျင်တွန်းအားက ဆင်းနှုန်းကိုလျှော့သည်။ ကစားကွင်းတွင် ဆင်းနှုန်းနှင့်ဘေးတိုက်နှုန်းလျှော့ပြီး အစိမ်းရောင်ကွင်းသို့ဆင်းပါ။',zh:'火箭向相反方向喷出气体，从而获得加速度。它携带推进剂，不需要推空气，所以在太空中也能工作。动力着陆时，发动机推力减缓下降。在游乐场里，按住推进减速，并在触及绿色平台前降低水平速度。'},source:'https://www.grc.nasa.gov/www/k-12/rocket/newton3r.html'},
{aliases:['spacesuit','space suit','ဝတ်စုံ','航天服','宇航服'],answer:{en:'A spacewalking suit is a small life-support system. It supplies oxygen, removes carbon dioxide, maintains pressure and manages temperature. Protective layers and flexible joints let astronauts work outside a spacecraft.',my:'အာကာသလမ်းလျှောက်ဝတ်စုံသည် အသက်ထောက်ပံ့စနစ်ငယ်တစ်ခုဖြစ်သည်။ အောက်ဆီဂျင်ပေး၊ ကာဗွန်ဒိုင်အောက်ဆိုဒ်ဖယ်၊ ဖိအားထိန်းပြီး အပူချိန်ကိုစီမံသည်။ အကာအကွယ်အလွှာနှင့်အဆစ်များက ယာဉ်အပြင်တွင် အလုပ်လုပ်နိုင်စေသည်။',zh:'出舱航天服是一套小型生命保障系统，提供氧气、去除二氧化碳、维持压力并控制温度。防护层和活动关节让宇航员能够在飞船外工作。'},source:'https://www.nasa.gov/centers-and-facilities/johnson/spacewalk-spacesuit-basics/'},
{aliases:['star','ကြယ်','恒星'],answer:{en:'A main-sequence star shines because nuclear fusion in its core releases energy. Blue stars have hotter surfaces than red stars. Mass strongly affects a star’s lifetime: massive stars burn fuel faster. A Sun-like star eventually becomes a white dwarf, not a black hole.',my:'ပင်မအစဉ်ကြယ်သည် အူတိုင်တွင် နျူကလီးယားပေါင်းစည်းမှုမှ စွမ်းအင်ထုတ်လွှတ်သဖြင့် လင်းနေသည်။ အပြာရောင်ကြယ်မျက်နှာပြင်က အနီရောင်ထက် ပိုပူသည်။ ထုထည်ဒြပ်ပမာဏကြီးသောကြယ်က လောင်စာပိုမြန်စွာသုံးသည်။ နေကဲ့သို့ကြယ်သည် နောက်ဆုံးတွင် တွင်းနက်မဟုတ်ဘဲ ကြယ်ဖြူပုဖြစ်လာသည်။',zh:'主序星依靠核心核聚变释放的能量发光。蓝色恒星的表面比红色恒星更热。质量深刻影响寿命：大质量恒星消耗燃料更快。像太阳这样的恒星最终成为白矮星，而不是黑洞。'},source:'https://science.nasa.gov/universe/stars/'}];
function has(text,term){if(/^[a-z0-9 *-]+$/i.test(term))return new RegExp('(^|[^a-z])'+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:s)?($|[^a-z])','i').test(text);return text.includes(term);}
export function detectLanguage(text,fallback='en'){return /[\u1000-\u109f]/.test(text)?'my':/[\u3400-\u9fff]/.test(text)?'zh':fallback;}
export function newSession(){return {topic:null,fact:null,seen:new Set()};}
export function answer(input,session,preferred='en',intent=null){const text=input.trim().toLowerCase(),lang=detectLanguage(text,preferred),t=ui[lang],result=(body,topic=null,source=null)=>({answer:body,topic,source,lang});
if(!text&&!intent)return result(t.clarify);
if(/^(hi|hello|hey|thanks|thank you|မင်္ဂလာပါ|ကျေးဇူး|你好|谢谢)[!！။。 .]*$/i.test(text))return result(t.greeting);
const follow=intent||(/another|different fact|more facts|နောက်အချက်|အချက်အသစ်|另一条|再来一个/.test(text)?'another':/explain more|more detail|tell me more|ပိုမိုရှင်း|အသေးစိတ်|详细|展开/.test(text)?'more':/simpler|simply|ရိုးရိုး|လွယ်လွယ်|简单/.test(text)?'simple':/^(why|ဘာကြောင့်|为什么)[?？။ ]*$/.test(text)?'more':null);
const topicHits=aliases.map((a,i)=>a.some(v=>has(text,v))||text===names[lang][i].toLowerCase()?i:-1).filter(i=>i>=0);
let topic=topicHits.length===1?topicHits[0]:null;
if(follow&&topicHits.length===0&&!facts(lang).some(f=>f[0].toLowerCase()===text)){topic=session.topic;if(topic===null)return result(t.clarify);if(follow==='simple')return result(overviews[lang][topic],topic,discoverySources[topic]);if(follow==='another'){const next=[0,1,2].map(n=>topic*3+n).find(i=>!session.seen.has(i));if(next===undefined)return result(t.end,topic);session.fact=next;session.seen.add(next);return result(facts(lang)[next].join('\n\n'),topic,discoverySources[topic]);}const i=session.fact??topic*3;return result(overviews[lang][topic]+'\n\n'+facts(lang)[i][1],topic,discoverySources[topic]);}
if((topic===1&&/hot|hottest|ပူ|热|温度/.test(text))||/hottest planet|planet is (?:the )?hottest|哪颗行星最热|အပူဆုံးဂြိုဟ်/.test(text)){session.topic=1;session.fact=null;return result(overviews[lang][1],1,discoverySources[1]);}
if(/largest planet|biggest planet|planet is (?:the )?largest|အကြီးဆုံးဂြိုဟ်|最大的行星|哪颗行星最大/.test(text)){session.topic=4;session.fact=null;return result(overviews[lang][4],4,discoverySources[4]);}
const exact=facts(lang).findIndex(f=>f[0].toLowerCase()===text);if(exact>=0){topic=Math.floor(exact/3);session.topic=topic;session.fact=exact;session.seen.add(exact);return result(facts(lang)[exact].join('\n\n'),topic,discoverySources[topic]);}
// Explicit topic + detail beats generic keyword overlap; unrelated questions do not get a random fact.
const scores=keywordRows.map((keys,i)=>({i,score:keys.reduce((n,k)=>n+(has(text,k)?1:0),0)})).filter(x=>x.score>0&&(topic===null||Math.floor(x.i/3)===topic)).sort((a,b)=>b.score-a.score);
if(scores.length&&(topic!==null||['olympus','ganymede','triton','sagittarius','aurora','奥林帕斯','木卫三','海卫一','人马座','极光'].some(k=>has(text,k)))){const best=scores[0],foundTopic=Math.floor(best.i/3);if(topicHits.length>1&&!topicHits.includes(foundTopic))return result(t.clarify);session.topic=foundTopic;session.fact=best.i;session.seen.add(best.i);return result(facts(lang)[best.i][1],foundTopic,discoverySources[foundTopic]);}
const broad=/tell me|about|explain|what is|what are|အကြောင်း|ရှင်းပြ|ဆိုတာ|ဘာလဲ|介绍|是什么|讲讲/.test(text)||aliases.flat().some(a=>text===a)||names[lang].some(n=>text===n.toLowerCase());
if(topic!==null){if(session.topic!==topic){session.fact=null;session.seen.clear();}session.topic=topic;if(broad&&!/taste|eat|pizza|president|အရသာ|စား|味道|总统/.test(text))return result(overviews[lang][topic],topic,discoverySources[topic]);return result(t.unsupported,topic);}
const extra=extraTopics.find(e=>e.aliases.some(a=>has(text,a)));if(extra){session.topic=null;session.fact=null;return result(extra.answer[lang],null,extra.source);}
return result(topicHits.length>1?t.clarify:t.fallback);
}
